SELECT sku, product_name, pack_size, gtin, selling_price_inr, cost_price_inr, flow_type
FROM store.products
WHERE lower(product_name) LIKE '%atta%' AND pack_size = '5 kg';

SELECT sku, name, pack, case_units, case_kg, flow, dc_slot, price_inr, cost_inr
FROM store.products
WHERE lower(name) LIKE '%atta%' AND pack = '5 kg';
